from pathlib import Path
from html import escape
import hashlib, json, re, shutil, urllib.request

ROOT = Path(__file__).resolve().parents[1]
BASE = ROOT / '.stitch-work/current-official'
OUT = BASE / 'airbnb-oct10-assets'
OUT.mkdir(exist_ok=True)
reference = json.loads((BASE / 'airbnb-oct10-browser-reference.json').read_text())
narrow = json.loads((BASE / 'airbnb-oct10-narrow-browser-reference.json').read_text())
bundle = json.loads((BASE / 'airbnb-oct10-asset-bundle.json').read_text())
records = []
mapping = {}
prior_path = BASE / 'airbnb-oct10-asset-provenance.json'
prior_assets = {a.get('source'): a for a in json.loads(prior_path.read_text()).get('assets', []) if a.get('local')} if prior_path.exists() else {}

def asset(url):
    if url in mapping:
        return mapping[url]
    previous = prior_assets.get(url)
    if previous and (BASE / previous['local']).is_file() and hashlib.sha256((BASE / previous['local']).read_bytes()).hexdigest() == previous['sha256']:
        mapping[url] = previous['local']
        records.append(previous)
        return mapping[url]
    exact = [a for a in bundle['assets'] if a['url'] == url]
    equivalents = [a for a in bundle['assets'] if a['url'].split('?')[0] == url.split('?')[0]]
    a = (exact or equivalents or [None])[0]
    data, mime, acquisition = None, None, None
    if a:
        data = Path(a['path']).read_bytes()
        mime = a['contentType']
        acquisition = {'method': 'browser pageAssets bundle', 'observed_url': url, 'bundled_url': a['url']}
    else:
        try:
            req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0', 'Accept': '*/*'})
            with urllib.request.urlopen(req, timeout=30) as response:
                data, mime = response.read(), response.headers.get_content_type()
            acquisition = {'method': 'public observed asset URL download after pageAssets did not bundle it', 'observed_url': url}
        except Exception as error:
            records.append({'source': url, 'error': str(error), 'fallback': 'observed remote URL'})
            mapping[url] = url
            return url
    suffix = {'image/avif': '.avif', 'image/jpeg': '.jpg', 'image/png': '.png', 'image/webp': '.webp', 'image/svg+xml': '.svg', 'font/woff2': '.woff2', 'application/font-woff2': '.woff2'}.get(mime, Path(url.split('?')[0]).suffix or '.bin')
    name = hashlib.sha256(url.encode()).hexdigest()[:16] + suffix
    path = OUT / name
    path.write_bytes(data)
    mapping[url] = 'airbnb-oct10-assets/' + name
    records.append({'source': url, 'local': mapping[url], 'mime': mime, 'bytes': len(data), 'sha256': hashlib.sha256(data).hexdigest(), **acquisition})
    return mapping[url]

font = asset('https://a0.muscache.com/airbnb/static/airbnb-dls-web/build/fonts/cereal-variable/AirbnbCerealVF_W_Wght.8816d9e5c3b6a860636193e36b6ac4e4.woff2')
for section in reference['sections']:
    for card in section['cards']:
        card['local_image'] = asset(card['image'])
for item in reference['navIcons'] + narrow['navIcons']:
    item['local_image'] = asset(item['src'])

if not (BASE / 'airbnb-sep26-draft-preserved.html').exists():
    shutil.copyfile(BASE / 'airbnb.html', BASE / 'airbnb-sep26-draft-preserved.html')

def svg(body, size=24, view='0 0 32 32', cls=''):
    return f'<svg class="{cls}" width="{size}" height="{size}" viewBox="{view}" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">{body}</svg>'

