HEART = svg('<path d="M16 28.667C23.167 23.782 30.333 17.783 30.333 10.558c0-1.85-.699-3.698-2.099-5.109-1.4-1.41-3.233-2.115-5.068-2.115-1.833 0-3.668.705-5.067 2.115L16 7.566l-2.099-2.117c-1.4-1.41-3.233-2.115-5.068-2.115-1.833 0-3.668.705-5.067 2.115-1.4 1.411-2.099 3.259-2.099 5.109 0 7.225 7.167 13.224 14.333 18.109Z"/>')
