MENU = svg('<path d="M8 10h16M8 16h16M8 22h16"/>', 20)
ARROW = svg('<path d="m13 8 8 8-8 8M6 16h15"/>', 16)
CHEVRON = svg('<path d="m12 7 9 9-9 9"/>', 12)
GLOBE = svg('<circle cx="16" cy="16" r="13"/><path d="M3 16h26M16 3c-8 8-8 18 0 26M16 3c8 8 8 18 0 26"/>', 16)
footer_icons = json.loads((BASE / 'airbnb-oct10-footer-icons.json').read_text())

tabs = []
for i, (desktop, mobile) in enumerate(zip(reference['navIcons'], narrow['navIcons'])):
    label = desktop['label']
    tabs.append(f'<button class="nav-tab {"selected" if i == 0 else ""}" type="button" role="tab" aria-selected="{str(i == 0).lower()}" data-search-type="{["homes", "homes", "experiences", "services"][i]}"><picture><source media="(max-width:743px)" srcset="{mobile["local_image"]}"><img src="{desktop["local_image"]}" alt=""></picture><span>{escape(label)}</span></button>')

feed = []
for index, (section, mobile_section) in enumerate(zip(reference['sections'], narrow['sections'])):
    subtitle = section['subtitle'].split('\n', 1)[1] if '\n' in section['subtitle'] else ''
    styles = f'--section-height:{section["rect"]["height"]}px;--narrow-height:{mobile_section["rect"]["height"]}px;--image-offset:{section["cards"][0]["imageRect"]["y"] - section["rect"]["y"]}px;--narrow-image-offset:{mobile_section["cards"][0]["imageRect"]["y"] - mobile_section["rect"]["y"]}px'
    cards = []
    for card in section['cards']:
        text = card['text'].replace('\xa0', ' ')
        price = re.search(r'\$[\d,]+\s*CAD\s*total', text)
        rating = re.search(r'([\d.]+) out of 5 average rating', text)
        parts = [line.strip() for line in text.splitlines() if line.strip()]
        after_title = parts[parts.index(card['title']) + 1:]
        date = after_title[0] if after_title and not after_title[0].startswith('$') else ''
        href = card['href'].split('&source_impression_id=')[0]
        badge = '<span class="card-badge">Guest favourite</span>' if 'Guest favourite' in text else ''
        cards.append(f'<article class="listing-card"><a class="listing-link" href="{escape(href)}" target="_blank" rel="noopener noreferrer"><span class="listing-media"><img src="{card["local_image"]}" alt="{escape(card["title"])}" loading="eager">{badge}</span><strong>{escape(card["title"])}</strong>{f"<span class=card-date>{escape(date)}</span>" if date else ""}<span class="card-stats">{escape(price.group(0)) if price else ""} · <span class="card-rating">★ {rating.group(1) if rating else ""}</span></span></a><button type="button" class="heart" aria-label="Add to wishlist: {escape(card["title"])}" aria-pressed="false">{HEART}</button></article>')
    cards.append(f'<a class="listing-card see-all" href="{escape(section["href"])}" target="_blank" rel="noopener noreferrer"><span class="listing-media">{ARROW}</span><strong>See all</strong></a>')
    feed.append(f'<section class="listing-section" style="{styles}" aria-labelledby="row-{index}"><div class="section-heading"><a href="{escape(section["href"])}" target="_blank" rel="noopener noreferrer"><h2 id="row-{index}">{escape(section["title"])}</h2><span class="heading-arrow">{ARROW}</span></a><div class="carousel-controls"><button class="carousel-previous" type="button" aria-label="Previous: {escape(section["title"])}" disabled>{CHEVRON}</button><button class="carousel-next" type="button" aria-label="Next: {escape(section["title"])}">{CHEVRON}</button></div></div>{f"<p class=section-subtitle>{escape(subtitle)}</p>" if subtitle else ""}<div class="carousel-track" tabindex="0" aria-label="{escape(section["title"])} listings">{"".join(cards)}</div></section>')

destinations = []
for d in reference['destinations']:
    parts = d['text'].strip().split('\n', 1)
    if len(parts) == 1:
        parts = d['text'].split('\xa0', 1)
    destinations.append(f'<a class="destination-item" href="{escape(d["href"])}" target="_blank" rel="noopener noreferrer"><strong>{escape(parts[0].strip())}</strong><span>{escape(parts[1].strip()) if len(parts) > 1 else ""}</span></a>')
footer_links = reference['footer'][:23]
footer_columns = []
for title, items in [('Support', footer_links[:7]), ('Hosting', footer_links[7:17]), ('Airbnb', footer_links[17:23])]:
    footer_columns.append(f'<div class="footer-column"><h3>{title}</h3>'+''.join(f'<a href="{escape(x["href"])}" target="_blank" rel="noopener noreferrer">{escape(x["text"])}</a>' for x in items)+'</div>')

