html = f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Airbnb | Vacation rentals, cabins, beach houses, &amp; more</title><meta name="description" content="Independent design study of the public Airbnb Canada homepage captured on 10 October 2026. Regional and personalized content may vary."><meta name="stitch-project" content="13625555706512007030"><style>{css}</style></head><body><h1 class="sr-only">Airbnb homepage</h1>
<header class="site-header" id="site-header"><a class="brand" href="https://www.airbnb.ca/" target="_blank" rel="noopener noreferrer" aria-label="Airbnb homepage"><img src="airbnb-assets/airbnb-wordmark.svg" alt="Airbnb"></a><div class="main-nav" role="tablist" aria-label="Find stays, experiences or services">{''.join(tabs)}</div><div class="header-actions"><a class="host" href="https://www.airbnb.ca/host/homes" target="_blank" rel="noopener noreferrer">Become a host</a><a class="round-action" href="https://www.airbnb.ca/login" target="_blank" rel="noopener noreferrer" aria-label="Log in or sign up">{PROFILE}</a><button class="round-action menu" type="button" aria-label="Main navigation menu" aria-expanded="false" aria-controls="menu-popover">{MENU}</button></div><form class="search-form" id="desktop-search"><div class="search-field where"><label for="destination">Where</label><input id="destination" name="query" placeholder="Search destinations" autocomplete="off"></div><div class="search-field when"><label for="dates">When</label><input id="dates" name="check_in" placeholder="Add dates" onfocus="this.type='date'" onblur="if(!this.value)this.type='text'"></div><div class="search-field who"><label for="guests">Who</label><input id="guests" name="adults" type="number" min="1" max="16" placeholder="Add guests"></div><button class="search-submit" type="submit" aria-label="Search">{SEARCH}</button></form><button class="compact-search" type="button" data-open-search><img src="{reference['navIcons'][1]['local_image']}" alt=""><span>Anywhere</span><span>Anytime</span><span>Add guests</span><i class="small-search">{SEARCH}</i></button><button class="mobile-search" type="button" data-open-search>{SEARCH}<span>Start your search</span></button><nav class="menu-popover" id="menu-popover" hidden><a href="https://www.airbnb.ca/help/home" target="_blank" rel="noopener noreferrer">Help Centre</a><a href="https://www.airbnb.ca/host/homes" target="_blank" rel="noopener noreferrer">Become a host</a><a href="https://www.airbnb.ca/login" target="_blank" rel="noopener noreferrer">Log in or sign up</a></nav></header>
<main id="site-content"><div class="feed">{''.join(feed)}</div><section class="inspiration"><h2>Inspiration for future getaways</h2><nav class="inspiration-tabs" aria-label="Getaway categories">{''.join('<a href="https://www.airbnb.ca/" target="_blank" rel="noopener noreferrer">'+x+'</a>' for x in ['Popular','Coastal','Islands','Lakes','Mountains','Outdoors','Things to do'])}</nav><div class="destination-grid">{''.join(destinations)}<button type="button" class="show-more" aria-expanded="false">Show more⌄</button></div></section></main><footer class="site-footer"><h2 class="sr-only">Site Footer</h2><div class="footer-columns">{''.join(footer_columns)}</div><div class="footer-bottom"><div class="footer-locales"><button type="button" data-official-locale>{GLOBE}English (CA)</button><button type="button" data-official-locale>$ &nbsp;CAD</button><div class="footer-social"><a href="https://www.facebook.com/airbnb" target="_blank" rel="noopener noreferrer" aria-label="Navigate to Facebook">{footer_icons["facebook"]}</a><a href="https://twitter.com/airbnb" target="_blank" rel="noopener noreferrer" aria-label="Navigate to Twitter">{footer_icons["twitter"]}</a><a href="https://instagram.com/airbnb" target="_blank" rel="noopener noreferrer" aria-label="Navigate to Instagram">{footer_icons["instagram"]}</a></div></div><div class="footer-legal"><span>© 2026 Airbnb, Inc.<b class="separator-first"> · </b></span><a href="https://www.airbnb.ca/terms/privacy_policy" target="_blank" rel="noopener noreferrer">Privacy</a> · <a href="https://www.airbnb.ca/terms" target="_blank" rel="noopener noreferrer">Terms</a></div></div></footer><nav class="mobile-bottom" aria-label="Main navigation"><a href="#site-content" aria-current="page">{SEARCH}Explore</a><a href="https://www.airbnb.ca/wishlists" target="_blank" rel="noopener noreferrer">{HEART}Wishlists</a><a href="https://www.airbnb.ca/login" target="_blank" rel="noopener noreferrer">{PROFILE}Log in</a></nav>
<dialog class="search-dialog" id="search-dialog"><button class="dialog-close" type="button" aria-label="Close search">×</button><h2>Where to?</h2><form class="dialog-form" id="dialog-search"><label>Where<input name="query" placeholder="Search destinations" autocomplete="off"></label><label>When<input name="check_in" type="date"></label><label>Who<input name="adults" type="number" min="1" max="16" placeholder="Add guests"></label><button class="search-submit" type="submit">Search</button></form></dialog>
<script>
const header=document.getElementById('site-header');const syncHeader=()=>header.classList.toggle('compact',window.scrollY>80);window.addEventListener('scroll',syncHeader,{{passive:true}});syncHeader();
let searchType='homes';const dialog=document.getElementById('search-dialog');document.querySelectorAll('[data-open-search]').forEach(b=>b.addEventListener('click',()=>dialog.showModal()));document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{{if(e.target===dialog)dialog.close()}});
document.querySelectorAll('.nav-tab').forEach(tab=>tab.addEventListener('click',()=>{{document.querySelectorAll('.nav-tab').forEach(x=>{{x.classList.remove('selected');x.setAttribute('aria-selected','false')}});tab.classList.add('selected');tab.setAttribute('aria-selected','true');searchType=tab.dataset.searchType;if(searchType!=='homes')dialog.showModal()}}));
document.querySelectorAll('form').forEach(form=>form.addEventListener('submit',event=>{{event.preventDefault();const values=new FormData(form);const city=String(values.get('query')||'').trim();const url=new URL('https://www.airbnb.ca/s/'+(city?encodeURIComponent(city)+'/':'')+searchType);if(values.get('check_in'))url.searchParams.set('check_in',values.get('check_in'));if(values.get('adults'))url.searchParams.set('adults',values.get('adults'));window.open(url.href,'_blank','noopener,noreferrer')}}));
document.querySelectorAll('.carousel-controls').forEach(controls=>{{const track=controls.closest('section').querySelector('.carousel-track');const previous=controls.querySelector('.carousel-previous');const next=controls.querySelector('.carousel-next');const sync=()=>{{previous.disabled=track.scrollLeft<2;next.disabled=track.scrollLeft>=track.scrollWidth-track.clientWidth-2}};previous.addEventListener('click',()=>track.scrollBy({{left:-track.clientWidth,behavior:'smooth'}}));next.addEventListener('click',()=>track.scrollBy({{left:track.clientWidth,behavior:'smooth'}}));track.addEventListener('scroll',sync,{{passive:true}});sync()}});
document.querySelectorAll('.heart').forEach(button=>button.addEventListener('click',()=>{{button.setAttribute('aria-pressed',String(button.getAttribute('aria-pressed')!=='true'))}}));
const menuButton=document.querySelector('.menu');const popover=document.getElementById('menu-popover');menuButton.addEventListener('click',()=>{{popover.hidden=!popover.hidden;menuButton.setAttribute('aria-expanded',String(!popover.hidden))}});document.addEventListener('keydown',e=>{{if(e.key==='Escape'){{popover.hidden=true;menuButton.setAttribute('aria-expanded','false')}}}});document.querySelector('.show-more').addEventListener('click',e=>{{const open=e.currentTarget.parentElement.classList.toggle('expanded');e.currentTarget.setAttribute('aria-expanded',String(open));e.currentTarget.textContent=open?'Show less⌃':'Show more⌄'}});document.querySelectorAll('[data-official-locale]').forEach(b=>b.addEventListener('click',()=>window.open('https://www.airbnb.ca/?locale=en','_blank','noopener,noreferrer')));
</script></body></html>'''
(BASE / 'airbnb.html').write_text(html)
(BASE / 'airbnb-oct10-asset-provenance.json').write_text(json.dumps({'sourcePage': reference['sourceUrl'], 'observedAt': reference['observedAt'], 'notes': 'Independent study of one public-session regional variant. Existing logo retained with its separate recorded provenance. Photos/fonts/icons remain their owners property. Original reference and provider output are preserved separately.', 'assets': records}, ensure_ascii=False, indent=2) + '\n')
print(json.dumps({'output': str(BASE / 'airbnb.html'), 'sections': len(reference['sections']), 'cards': sum(len(s['cards']) for s in reference['sections']), 'assets': len(records), 'asset_errors': [x for x in records if 'error' in x], 'html_sha256': hashlib.sha256(html.encode()).hexdigest()}, ensure_ascii=False, indent=2))
